import{_ as a,o as d,c as r,ae as e}from"./chunks/framework.Co1PSFSm.js";const b=JSON.parse('{"title":"第14周：综合实战工作坊上","description":"","frontmatter":{"title":"第14周：综合实战工作坊上"},"headers":[],"relativePath":"week14/index.md","filePath":"week14/index.md"}'),l={name:"week14/index.md"};function i(o,t,h,n,s,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<p>第14周讲义</p><p><strong>综合实战工作坊（上）—— 从数据到洞察</strong></p><p><em>12周的知识，在这一周里融会贯通</em></p><h1 id="一、情景导入-小林的故事" tabindex="-1"><strong>一、情景导入（小林的故事）</strong> <a class="header-anchor" href="#一、情景导入-小林的故事" aria-label="Permalink to &quot;**一、情景导入（小林的故事）**&quot;">​</a></h1><p>月底了。老板把小林叫到办公室：“下个季度的运营策略会议在两周后，我需要你提交一份完整的客户数据分析报告。报告要回答三个问题：我们的客户是谁？他们怎么样？我们该怎么办？”</p><p>小林深吸一口气。这不再是单一知识点的练习，而是要把整个学期学到的所有内容整合起来，完成一份真正有商业价值的分析报告。</p><p>她打开笔记本，列出了需要用到的知识模块：</p><ul><li>数据清洗（W2）</li><li>客户画像与RFM（W3）</li><li>数据可视化（W4）</li><li>客户细分（W5）</li><li>CLV分析（W6）</li><li>流失预警（W7）</li><li>A/B测试（W8）</li><li>个性化推荐（W9）</li><li>全渠道体验（W10）</li><li>会员体系（W11）</li><li>数据合规（W12）</li><li>AI辅助分析（W13）</li></ul><p><strong>12周的知识，要在这一周里融会贯通。这就是“综合实战”的意义。</strong></p><h1 id="二、核心知识点" tabindex="-1"><strong>二、核心知识点</strong> <a class="header-anchor" href="#二、核心知识点" aria-label="Permalink to &quot;**二、核心知识点**&quot;">​</a></h1><h2 id="_1-完整的客户分析框架" tabindex="-1"><strong>1. 完整的客户分析框架</strong> <a class="header-anchor" href="#_1-完整的客户分析框架" aria-label="Permalink to &quot;**1. 完整的客户分析框架**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>分析内容</th><th>使用的方法/工具</th><th>产出</th></tr></thead><tbody><tr><td>数据准备</td><td>数据收集、清洗、整理</td><td>Excel + AI辅助</td><td>清洁的数据集</td></tr><tr><td>客户认知</td><td>客户是谁？有什么特征？</td><td>画像分析、RFM、客户细分</td><td>客户画像、细分报告</td></tr><tr><td>价值评估</td><td>客户值多少钱？</td><td>CLV分析、CAC计算</td><td>CLV报告</td></tr><tr><td>行为洞察</td><td>客户在做什么？为什么？</td><td>流失预警、购买路径分析</td><td>行为洞察报告</td></tr><tr><td>策略制定</td><td>我们该怎么办？</td><td>个性化推荐、会员体系设计</td><td>运营策略方案</td></tr><tr><td>效果验证</td><td>策略有效吗？</td><td>A/B测试</td><td>测试报告</td></tr><tr><td>合规保障</td><td>数据使用合法吗？</td><td>隐私合规评估</td><td>合规报告</td></tr></tbody></table><h2 id="_2-数据驱动决策流程" tabindex="-1"><strong>2. 数据驱动决策流程</strong> <a class="header-anchor" href="#_2-数据驱动决策流程" aria-label="Permalink to &quot;**2. 数据驱动决策流程**&quot;">​</a></h2><p><strong>六步决策法：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>关键问题</th><th>工具</th></tr></thead><tbody><tr><td>1. 定义问题</td><td>明确要解决的业务问题</td><td>“我们面临什么挑战？”</td><td>头脑风暴、业务访谈</td></tr><tr><td>2. 收集数据</td><td>确定需要什么数据</td><td>“需要哪些数据来回答这个问题？”</td><td>数据库、问卷、AI辅助</td></tr><tr><td>3. 分析数据</td><td>用合适的方法分析数据</td><td>“数据告诉了我们什么？”</td><td>AI工具、Excel、Power BI</td></tr><tr><td>4. 得出洞察</td><td>从数据中提取商业洞察</td><td>“这些数据意味着什么？”</td><td>人的判断力 + AI辅助</td></tr><tr><td>5. 制定策略</td><td>基于洞察制定行动方案</td><td>“我们应该怎么做？”</td><td>团队讨论、AI建议</td></tr><tr><td>6. 执行验证</td><td>执行策略并验证效果</td><td>“策略有效吗？需要调整吗？”</td><td>A/B测试、数据监控</td></tr></tbody></table><h2 id="_3-分析报告的结构" tabindex="-1"><strong>3. 分析报告的结构</strong> <a class="header-anchor" href="#_3-分析报告的结构" aria-label="Permalink to &quot;**3. 分析报告的结构**&quot;">​</a></h2><p><strong>一份好的分析报告应该包含：</strong></p><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>篇幅建议</th></tr></thead><tbody><tr><td>执行摘要</td><td>核心发现和建议（老板最先看这个）</td><td>1页</td></tr><tr><td>分析背景</td><td>为什么要做这个分析</td><td>半页</td></tr><tr><td>数据说明</td><td>数据来源、时间范围、样本量</td><td>半页</td></tr><tr><td>分析发现</td><td>核心分析结果（图表+文字）</td><td>5-8页</td></tr><tr><td>策略建议</td><td>基于数据的具体建议</td><td>2-3页</td></tr><tr><td>附录</td><td>详细数据和分析过程</td><td>按需</td></tr></tbody></table><p>**关键原则：**老板只给你5分钟，你的报告必须在前1页就让他看到核心结论。</p><h2 id="_4-ai辅助综合分析" tabindex="-1"><strong>4. AI辅助综合分析</strong> <a class="header-anchor" href="#_4-ai辅助综合分析" aria-label="Permalink to &quot;**4. AI辅助综合分析**&quot;">​</a></h2><ul><li>用AI帮你快速完成多个分析模块</li><li>用AI帮你生成可视化图表</li><li>用AI帮你撰写报告初稿</li><li>你来整合、验证、提炼核心洞察</li></ul><h1 id="三、实操指南-搭建完整分析框架" tabindex="-1"><strong>三、实操指南：搭建完整分析框架</strong> <a class="header-anchor" href="#三、实操指南-搭建完整分析框架" aria-label="Permalink to &quot;**三、实操指南：搭建完整分析框架**&quot;">​</a></h1><h2 id="步骤一-明确分析目标" tabindex="-1"><strong>步骤一：明确分析目标</strong> <a class="header-anchor" href="#步骤一-明确分析目标" aria-label="Permalink to &quot;**步骤一：明确分析目标**&quot;">​</a></h2><p>确定报告要回答的核心业务问题</p><h2 id="步骤二-梳理分析模块" tabindex="-1"><strong>步骤二：梳理分析模块</strong> <a class="header-anchor" href="#步骤二-梳理分析模块" aria-label="Permalink to &quot;**步骤二：梳理分析模块**&quot;">​</a></h2><p>列出需要用到的分析方法和工具</p><h2 id="步骤三-准备数据" tabindex="-1"><strong>步骤三：准备数据</strong> <a class="header-anchor" href="#步骤三-准备数据" aria-label="Permalink to &quot;**步骤三：准备数据**&quot;">​</a></h2><p>收集、清洗、整理所需数据</p><h2 id="步骤四-逐模块分析" tabindex="-1"><strong>步骤四：逐模块分析</strong> <a class="header-anchor" href="#步骤四-逐模块分析" aria-label="Permalink to &quot;**步骤四：逐模块分析**&quot;">​</a></h2><p>按框架逐个完成分析模块</p><h2 id="步骤五-整合发现" tabindex="-1"><strong>步骤五：整合发现</strong> <a class="header-anchor" href="#步骤五-整合发现" aria-label="Permalink to &quot;**步骤五：整合发现**&quot;">​</a></h2><p>将各模块的分析结果整合，提炼核心洞察</p><h2 id="步骤六-撰写报告初稿" tabindex="-1"><strong>步骤六：撰写报告初稿</strong> <a class="header-anchor" href="#步骤六-撰写报告初稿" aria-label="Permalink to &quot;**步骤六：撰写报告初稿**&quot;">​</a></h2><p>按照报告结构撰写分析报告</p><p><strong>本周任务：完成分析报告初稿</strong></p><ul><li>本周（W14）：完成数据准备 + 分析 + 报告初稿</li><li>下周（W15）：将报告浓缩为5分钟数据故事演讲</li></ul><h1 id="四、课堂练习" tabindex="-1"><strong>四、课堂练习</strong> <a class="header-anchor" href="#四、课堂练习" aria-label="Permalink to &quot;**四、课堂练习**&quot;">​</a></h1><h2 id="练习1-分析框架设计" tabindex="-1"><strong>练习1：分析框架设计</strong> <a class="header-anchor" href="#练习1-分析框架设计" aria-label="Permalink to &quot;**练习1：分析框架设计**&quot;">​</a></h2><p>使用课程提供的综合数据集，设计一个完整的客户分析框架：</p><ol><li>明确3个核心业务问题</li><li>列出需要用到的分析模块（至少5个）</li><li>画出分析流程图（可以用文字描述）</li><li>确定每个模块的输入数据和预期产出</li></ol><h2 id="练习2-数据准备" tabindex="-1"><strong>练习2：数据准备</strong> <a class="header-anchor" href="#练习2-数据准备" aria-label="Permalink to &quot;**练习2：数据准备**&quot;">​</a></h2><p>使用课程提供的原始数据集，完成：</p><ol><li>数据质量检查（参照W2的数据清洗方法）</li><li>数据清洗和整理</li><li>使用AI工具辅助数据探索</li><li>记录数据准备过程</li></ol><h1 id="五、课后作业" tabindex="-1"><strong>五、课后作业</strong> <a class="header-anchor" href="#五、课后作业" aria-label="Permalink to &quot;**五、课后作业**&quot;">​</a></h1><p><strong>P4-2 分析报告初稿</strong></p><p>使用课程提供的综合数据集，完成一份完整的客户数据分析报告初稿，包含：</p><ol><li>执行摘要（1页）</li><li>分析背景和数据说明</li><li>至少3个分析模块的详细分析（客户细分、CLV、流失预警等）</li><li>每个分析模块需包含：数据表格/图表 + 分析结论</li><li>基于分析结果的策略建议（至少3条）</li><li>使用AI工具辅助分析和报告撰写</li></ol><p>**提交要求：**完整的分析报告初稿（Word/PPT格式，不少于10页）。</p><hr><h2 id="📊-本课数据" tabindex="-1">📊 本课数据 <a class="header-anchor" href="#📊-本课数据" aria-label="Permalink to &quot;📊 本课数据&quot;">​</a></h2><p>本课将综合运用之前所有数据集，使用 AI 工具进行完整分析：</p><table tabindex="0"><thead><tr><th>数据集</th><th>说明</th><th>下载</th></tr></thead><tbody><tr><td><a href="/data/customer_data.csv">客户主数据</a></td><td>1000位客户信息</td><td><a href="/data/customer_data.csv">下载</a></td></tr><tr><td><a href="/data/transaction_data.csv">订单商品明细</a></td><td>约2000条订单明细</td><td><a href="/data/transaction_data.csv">下载</a></td></tr><tr><td><a href="/data/customer_behavior.csv">客户行为数据</a></td><td>客户行为指标</td><td><a href="/data/customer_behavior.csv">下载</a></td></tr><tr><td><a href="/data/churn_risk_data.csv">流失预警数据</a></td><td>流失风险评分</td><td><a href="/data/churn_risk_data.csv">下载</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">AI 分析建议</p><p>将数据上传到 Kimi（kimi.moonshot.cn），用自然语言描述分析需求，让 AI 辅助你完成客户分析全流程。</p></div>',53)])])}const u=a(l,[["render",i]]);export{b as __pageData,u as default};
